#!/usr/bin/env node
/**
 * Resolve representative imports with the official TypeScript compiler API.
 *
 * Usage:
 *   npm install --no-save typescript@5.9.3
 *   node reproduction/tsc_resolve_case.mjs \
 *     --root /path/to/lexical \
 *     --source packages/lexical-react/src/ReactExtension.tsx \
 *     --specifier lexical \
 *     --specifier @lexical/react/LexicalComposerContext
 *
 * The parsed configuration is generated by TypeScript itself, so this is an
 * independent check that the JSONC config is valid and that the configured
 * `paths` mappings identify the claimed implementation files.
 */
import path from "node:path";
import process from "node:process";
import { createRequire } from "node:module";

const require = createRequire(import.meta.url);
let ts;
try {
  ts = require("typescript");
} catch {
  console.error("Install TypeScript first, e.g. npm install --no-save typescript@5.9.3");
  process.exit(2);
}

const args = process.argv.slice(2);
function valueAfter(flag) {
  const index = args.indexOf(flag);
  return index >= 0 ? args[index + 1] : undefined;
}
function allAfter(flag) {
  const values = [];
  for (let i = 0; i < args.length; i += 1) {
    if (args[i] === flag && args[i + 1]) values.push(args[i + 1]);
  }
  return values;
}

const root = path.resolve(valueAfter("--root") ?? ".");
const sourceRelative = valueAfter("--source");
const specifiers = allAfter("--specifier");
if (!sourceRelative || specifiers.length === 0) {
  console.error("--source and at least one --specifier are required");
  process.exit(2);
}

const configPath = ts.findConfigFile(root, ts.sys.fileExists, "tsconfig.json");
if (!configPath) {
  console.error(`No tsconfig.json found at ${root}`);
  process.exit(2);
}
const read = ts.readConfigFile(configPath, ts.sys.readFile);
if (read.error) {
  console.error(ts.formatDiagnosticsWithColorAndContext([read.error], {
    getCanonicalFileName: (f) => f,
    getCurrentDirectory: ts.sys.getCurrentDirectory,
    getNewLine: () => ts.sys.newLine,
  }));
  process.exit(1);
}
const parsed = ts.parseJsonConfigFileContent(
  read.config,
  ts.sys,
  path.dirname(configPath),
  undefined,
  configPath,
);
const sourcePath = path.resolve(root, sourceRelative);
const resolutions = specifiers.map((specifier) => {
  const result = ts.resolveModuleName(
    specifier,
    sourcePath,
    parsed.options,
    ts.sys,
    undefined,
    undefined,
    ts.ModuleKind.ESNext,
  );
  const resolved = result.resolvedModule;
  return {
    specifier,
    resolved_path: resolved ? path.relative(root, resolved.resolvedFileName).split(path.sep).join("/") : null,
    extension: resolved ? ts.Extension[resolved.extension] ?? String(resolved.extension) : null,
    is_external_library_import: resolved?.isExternalLibraryImport ?? null,
  };
});

console.log(JSON.stringify({
  typescript_version: ts.version,
  config_path: path.relative(root, configPath).split(path.sep).join("/"),
  config_error: null,
  paths_pattern_count: Object.keys(parsed.options.paths ?? {}).length,
  source_file: sourceRelative,
  resolutions,
}, null, 2));
